\newcommand{\NN}{\mathbb{N}}
\newcommand{\rev}{\operatorname{rev}}
\newcommand{\dens}{\operatorname{dens}}
\newcommand{\ccount}{\operatorname{cusickCount}}

\title{Binary Digit-Reversal Invariance of Cusick Densities:\\
Two Exact, Verified Five-Bit Instances}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}
\begin{abstract}
Let $s_2(n)$ denote the binary digit sum (the number of $1$s in the base-$2$
expansion of $n$). For a fixed shift $t \ge 1$, Cusick's density is
\[
c_t = \lim_{N \to \infty} \frac{1}{N}\,\#\{0 \le n < N : s_2(n+t) \ge s_2(n)\}.
\]
The Drmota--Kauers--Spiegelhofer theorem (2016) establishes the explicit bias bound
$c_t \ge \tfrac{1}{2} + 2^{-(2 s_2(t)+1)}$, in particular $c_t > 1/2$ for all $t$
(Cusick's conjecture). A structural prerequisite is that the predicate
$P_t(n) := [\,s_2(n+t) \ge s_2(n)\,]$ is purely periodic in $n$ with period
$2^{L+s_2(t)}$ whenever $t < 2^L$, making each $c_t$ a dyadic rational computable from a
single period. We exploit this to record and prove a discrete symmetry: the Cusick
density appears invariant under reversal of the binary digits of $t$. We give two exact,
fully formalized instances for five-bit shifts. The reversal pair $(19,25)$, with
$19 = 10011_2$ and $25 = 11001_2$, satisfies $c_{19} = c_{25} = 41/64$; the reversal pair
$(23,29)$, with $23 = 10111_2$ and $29 = 11101_2$, satisfies $c_{23} = c_{29} = 75/128$.
The proofs combine a kernel computation of the per-period counts ($164$ over $[0,256)$ and
$300$ over $[0,512)$) with the general periodicity theorem to obtain equality of the
counts over every aligned block.
\end{abstract}

\maketitle

\section{Introduction}
The binary digit sum $s_2$ is among the most studied automatic sequences, and its
behavior under addition connects Gelfond's digit problems, the Thue--Morse sequence (the
parity of $s_2$), and dynamical transfer-operator methods. T.~W.~Cusick conjectured that
adding any fixed positive integer $t$ is biased toward not decreasing the digit sum: the
density $c_t = \dens\{n : s_2(n) \le s_2(n+t)\}$ satisfies $c_t > 1/2$ for every
$t \ge 1$. Drmota, Kauers, and Spiegelhofer proved the stronger explicit lower bound
\begin{equation}\label{eq:dks}
c_t \ge \frac{1}{2} + 2^{-(2 s_2(t)+1)},
\end{equation}
settling Cusick's conjecture quantitatively.

While the inequality direction is a theorem, the exact values and internal symmetries of
$\{c_t\}$ remain mysterious. This paper isolates one symmetry. Reversing the binary digits
of $t$ within its bit length preserves both $s_2(t)$ and the bit length $L$, hence the
fundamental period $2^{L+s_2(t)}$. It is far less obvious that it preserves the density
itself, because the density is governed by carry interactions depending on the arrangement
of the bits, not their count. We prove two exact instances of the digit-reversal
invariance conjecture $c_t = c_{\rev(t)}$ for five-bit shifts:
\[
c_{19} = c_{25} = \frac{41}{64}, \qquad c_{23} = c_{29} = \frac{75}{128}.
\]

\section{Definitions}
\begin{definition}[Binary digit sum]
For $n \in \NN$, $s_2(n) = \sum_{i \ge 0} \varepsilon_i(n)$ where
$n = \sum_{i\ge 0}\varepsilon_i(n)2^i$ with $\varepsilon_i(n)\in\{0,1\}$. Equivalently
$s_2(n)$ is the sum of the base-$2$ digit list of $n$.
\end{definition}

\begin{definition}[Computable copy]
Since the catalog's $s_2$ is \texttt{noncomputable}, a definitionally equal computable
copy $\texttt{s2compute}(n) := (\texttt{Nat.digits}\,2\,n).\texttt{sum}$ is introduced,
with $\texttt{s2compute}(n) = s_2(n)$ holding by reflexivity. This copy enables kernel
evaluation of the finite per-period counts.
\end{definition}

\begin{definition}[Cusick predicate and count]
For shift $t$ and window $N$, set $P_t(n) := [\,s_2(n) \le s_2(n+t)\,]$ and
\[
\ccount(t, N) := \#\{\,0 \le n < N : P_t(n)\,\}.
\]
\end{definition}

\begin{definition}[Cusick density]
When the limit exists, $c_t := \lim_{N\to\infty}\ccount(t,N)/N$. By periodicity it equals
$\ccount(t, 2^{L+s_2(t)})/2^{L+s_2(t)}$ for any $L$ with $t < 2^L$.
\end{definition}

\begin{definition}[Binary digit reversal]
For $t$ with bit length $L = \lvert \texttt{digits}_2 t\rvert$, the reversal $\rev(t)$ is
the integer whose binary digit list is that of $t$ read in reverse (within the $L$-bit
window). Reversal preserves $s_2$ and $L$. The pairs here are $\rev(19) = 25$ and
$\rev(23) = 29$.
\end{definition}

\section{Background: pure periodicity and dyadic rationality}
\begin{theorem}[Pure periodicity]\label{thm:per}
Let $t \ge 1$ and $L$ satisfy $t < 2^L$; put $M = L + s_2(t)$. Then for all $n$,
$P_t(n) \iff P_t(n \bmod 2^{M})$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $n = 2^{M} b + a$ with $a = n \bmod 2^{M}$. If $a + t < 2^{M}$, the
digit-concatenation identity $s_2(2^{M}b + x) = s_2(b) + s_2(x)$ ($x < 2^{M}$) cancels
$s_2(b)$ from both sides, so $P_t(n)\iff[s_2(a)\le s_2(a+t)]$, independent of $b$. If
$a + t \ge 2^{M}$, then $a > 2^{L}(2^{s_2(t)}-1)$ forces the top $s_2(t)$ bits of the
window to be $1$; adding $t$ annihilates them through a carry chain, so $s_2(n+t)<s_2(n)$
for every $b$ by strict subadditivity on overflow. The predicate is uniformly false,
again independent of $b$.
\end{proof}

\begin{theorem}[Exact scaling / dyadic rationality]\label{thm:scale}
With $M = L + s_2(t)$ and any $m \ge 0$,
$\ccount(t,\ 2^{M} m) = m \cdot \ccount(t,\ 2^{M})$. Hence
$c_t = \ccount(t, 2^{M})/2^{M}$ is a dyadic rational.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $m$, splitting $\mathrm{range}(2^{M}(m+1))$ into $\mathrm{range}(2^{M}m)$ and a
shifted copy of $\mathrm{range}(2^{M})$; Theorem~\ref{thm:per} makes the shifted block
contribute one more base count.
\end{proof}

\section{The reversal pairs}
\begin{center}
\begin{tabular}{ccccc}
$t$ & binary & $s_2(t)$ & $L$ & period $2^{L+s_2(t)}$ \\ \hline
$19$ & $10011_2$ & $3$ & $5$ & $256$ \\
$25$ & $11001_2$ & $3$ & $5$ & $256$ \\
$23$ & $10111_2$ & $4$ & $5$ & $512$ \\
$29$ & $11101_2$ & $4$ & $5$ & $512$ \\
\end{tabular}
\end{center}
Here $11001 = \overline{10011}$ and $11101 = \overline{10111}$, so $\rev(19)=25$ and
$\rev(23)=29$. The digit-sum facts $s_2(19)=s_2(25)=3$ and $s_2(23)=s_2(29)=4$ hold by
reflexivity.

\section{Base-block counts}
\begin{lemma}[Per-period counts]\label{lem:base}
\[
\ccount(19,256)=\ccount(25,256)=164, \qquad \ccount(23,512)=\ccount(29,512)=300.
\]
\end{lemma}
\begin{proof}
Each count is a finite enumeration over an explicit range. Replacing $s_2$ by its
definitionally equal computable copy, the four counts are discharged by kernel evaluation.
The base-block counts already coincide within each reversal pair: $164=164$ and $300=300$.
\end{proof}

\section{Exact counts over all aligned blocks}
\begin{theorem}[Exact block counts]\label{thm:block}
For every $m \ge 0$,
\[
\ccount(19,256m)=\ccount(25,256m)=164m, \qquad \ccount(23,512m)=\ccount(29,512m)=300m.
\]
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:scale} with $L=5$. For $t\in\{19,25\}$, $s_2(t)=3$ gives period
$256$ and base count $164$; for $t\in\{23,29\}$, $s_2(t)=4$ gives period $512$ and base
count $300$. Multiply by $m$.
\end{proof}

\section{Main results}
\begin{theorem}[Reversal pair $(19,25)$]\label{thm:1925}
For every $m \ge 0$, $\ccount(19,256m) = \ccount(25,256m)$, and consequently
\[
c_{19} = c_{25} = \frac{164}{256} = \frac{41}{64}.
\]
\end{theorem}
\begin{proof}
Both sides equal $164m$ by Theorem~\ref{thm:block}; dividing by $256m$ and letting
$m\to\infty$ gives the common density $41/64$.
\end{proof}

\begin{theorem}[Reversal pair $(23,29)$]\label{thm:2329}
For every $m \ge 0$, $\ccount(23,512m) = \ccount(29,512m)$, and consequently
\[
c_{23} = c_{29} = \frac{300}{512} = \frac{75}{128}.
\]
\end{theorem}
\begin{proof}
Both sides equal $300m$ by Theorem~\ref{thm:block}; dividing by $512m$ and letting
$m\to\infty$ gives the common density $75/128$.
\end{proof}

\section{Consistency with the DKS bound}
For $t=19$ ($s_2=3$), \eqref{eq:dks} gives $c_{19}\ge \tfrac12+2^{-7}=\tfrac{65}{128}
\approx 0.5078$, while $c_{19}=\tfrac{41}{64}\approx 0.6406$. For $t=23$ ($s_2=4$), the
bound gives $c_{23}\ge\tfrac12+2^{-9}=\tfrac{257}{512}\approx 0.5020$, while
$c_{23}=\tfrac{75}{128}\approx 0.5859$. The exact values exceed the guarantee and are
identical within each reversal pair.

\section{Discussion and future work}
The values $c_{19}=c_{25}=41/64$ and $c_{23}=c_{29}=75/128$ enrich the explicit catalog
($c_1=3/4$, $c_3=11/16$, $c_7=43/64$, $c_{2^k}=3/4$, $\dots$) and give the first rigorous,
exact confirmations of binary digit-reversal invariance among five-bit shifts. Distinct
shifts with equal digit sum and bit length need not share a density, so the symmetry is a
genuine constraint on the carry bookkeeping.

\begin{conjecture}[Digit-reversal invariance]
For every $t \ge 1$, $c_t = c_{\rev(t)}$.
\end{conjecture}

A proof strategy is to build, on the fundamental period $[0,2^{L+s_2(t)})$, a
measure-preserving bijection $n\mapsto\rho(n)$ with
$P_t(n)\iff P_{\rev(t)}(\rho(n))$, yielding equality of the counts at once. A clean target
lemma is $s_2(\rev_L(n)) = s_2(n)$ together with a carry correspondence under window
reversal.

\section{Conclusion}
We stated and proved, with full formal verification of every count, two exact instances of
binary digit-reversal invariance of Cusick densities, reducing via pure periodicity to the
per-period coincidences $164=164$ and $300=300$.

\begin{thebibliography}{9}
\bibitem{DKS} M.~Drmota, M.~Kauers, L.~Spiegelhofer,
\emph{On a conjecture of Cusick concerning the sum of digits of $n$ and $n+t$},
SIAM J. Discrete Math. \textbf{30} (2016), 621--649.
\bibitem{Cusick} T.~W.~Cusick, \emph{On a conjecture concerning the sum of digits of
$n$ and $n+t$}, manuscript.
\end{thebibliography}

