from typing import List

def s2(n: int) -> int:
    return bin(n).count("1")

def cusick_period(t: int) -> int:
    return 2 ** (t.bit_length() + s2(t))

def cusick_count(t: int, N: int) -> int:
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))

def check_scaling(t: int, ms: List[int]) -> None:
    P: int = cusick_period(t)
    base: int = cusick_count(t, P)
    print(f"t={t}: period {P}, base count {base}")
    for m in ms:
        got: int = cusick_count(t, P * m)
        print(f"  cusickCount({t}, {P*m}) = {got}; predicted {base*m}; ok={got==base*m}")

if __name__ == "__main__":
    check_scaling(19, [1, 2, 3, 4, 5])
    check_scaling(23, [1, 2, 3, 4])

